import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"es/concepts/endpoints.md","filePath":"es/concepts/endpoints.md","lastUpdated":1784903584000}'),o={name:"es/concepts/endpoints.md"};function i(d,e,r,p,c,l){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h1><p>Un endpoint es un método HTTP + ruta específico que puede ser invocado (por ejemplo, <code>GET /api/users/{id}</code>). Los endpoints son las operaciones de API reales que el LLM descubre, inspecciona y llama.</p><h2 id="estructura" tabindex="-1">Estructura <a class="header-anchor" href="#estructura" aria-label="Permalink to &quot;Estructura&quot;">​</a></h2><p>Cada endpoint contiene:</p><ul><li><strong>Método HTTP</strong>: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>Ruta</strong>: <code>/api/v1/users/{id}</code></li><li><strong>Resumen</strong>: una descripción corta de lo que hace el endpoint — muy útil para que el LLM entienda su propósito de un vistazo</li><li><strong>Descripción</strong>: una explicación detallada del comportamiento, parámetros y casos de uso del endpoint</li><li><strong>Parámetros</strong>: ruta, consulta, encabezado, cookie</li><li><strong>Cuerpo de solicitud</strong>: para POST/PUT/PATCH</li><li><strong>Respuestas</strong>: códigos de estado y esquemas de respuesta</li></ul><p>Los campos <code>summary</code> y <code>description</code> provienen del archivo OpenAPI/Swagger/Postman. Son la forma principal en que el LLM entiende lo que hace un endpoint. Los resúmenes bien escritos hacen que el descubrimiento de endpoints sea mucho más efectivo.</p><h2 id="herramientas-mcp-para-endpoints" tabindex="-1">Herramientas MCP para Endpoints <a class="header-anchor" href="#herramientas-mcp-para-endpoints" aria-label="Permalink to &quot;Herramientas MCP para Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Descripción</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>Todos los endpoints en una especificación</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Endpoints en una colección</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Endpoints en una etiqueta</td></tr><tr><td><code>endpoint_by_id</code></td><td>Resumen rápido del endpoint</td></tr><tr><td><code>inspect</code></td><td>Detalles completos del endpoint (esquemas, parámetros)</td></tr><tr><td><code>invoke</code></td><td>Llamar al endpoint</td></tr><tr><td><code>search</code></td><td>Buscar endpoints por texto</td></tr></tbody></table><h2 id="endpoints-obsoletos" tabindex="-1">Endpoints Obsoletos <a class="header-anchor" href="#endpoints-obsoletos" aria-label="Permalink to &quot;Endpoints Obsoletos&quot;">​</a></h2><p>Los endpoints marcados como <code>deprecated</code> en la especificación se muestran con un aviso al ser inspeccionados.</p><h2 id="configuracion" tabindex="-1">Configuración <a class="header-anchor" href="#configuracion" aria-label="Permalink to &quot;Configuración&quot;">​</a></h2><p>Los endpoints son <strong>de solo lectura</strong> desde la perspectiva de swag2mcp. No hay configuraciones YAML para endpoints — no puede agregar, eliminar, renombrar ni modificarlos en <code>swag2mcp.yaml</code>.</p><p>Para cambiar endpoints (agregar nuevos, actualizar resúmenes, modificar parámetros, marcar como obsoletos), edite el archivo OpenAPI/Swagger/Postman original y ejecute <code>swag2mcp update</code> para volver a analizar y reindexar.</p><h2 id="ejemplo" tabindex="-1">Ejemplo <a class="header-anchor" href="#ejemplo" aria-label="Permalink to &quot;Ejemplo&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Consulta: &quot;Muestra detalles para GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Resultado:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  Resumen: Find pet by ID</span></span>
<span class="line"><span>  Descripción: Returns a single pet by its ID</span></span>
<span class="line"><span>  Parámetros:</span></span>
<span class="line"><span>    - petId (path, integer, required)</span></span>
<span class="line"><span>  Respuestas:</span></span>
<span class="line"><span>    - 200: Pet object</span></span>
<span class="line"><span>    - 400: Error</span></span>
<span class="line"><span>    - 404: Not found</span></span></code></pre></div>`,15)])])}const h=a(o,[["render",i]]);export{m as __pageData,h as default};
